// Gateway build script — generates service route registry.
//
// Scans ALL Pre-Proc/*/Sources/Services/*/service.json at compile time
// and generates auto_service_registry.rs with conditional compilation gates
// for every service's cargo feature.
// Module scanning has been removed — modules no longer hold backends;
// all backend logic lives in Service units.

use std::fs;
use std::path::Path;

/// Namespace 路由别名：无自身 service 的 namespace 可在此声明映射到目标 namespace。
/// 生成的 `register_service_routes()` 会将别名展开到目标 namespace 的 match 分支。
/// 新增 namespace 时，若需别名路由，在此添加即可——无需手动编辑 service_registry.rs。
const NAMESPACE_ALIASES: &[(&str, &str)] = &[("Cosmic-Tools", "Alioth")];

fn main() {
    // === Ontology 一致性预检（Gateway 构建门禁） ===
    ontology_preflight_check();

    // === Service 单元扫描（所有 namespace） ===
    let mut service_entries: Vec<ServiceEntry> = Vec::new();

    // 扫描 Pre-Proc/ 下所有 namespace 目录
    let preproc_root =
        std::env::var("SERVICES_SOURCE_PATH").unwrap_or_else(|_| "../../Pre-Proc".to_string());
    let preproc_dir = Path::new(&preproc_root);
    // 只监听具体 service.json 文件变化（单个文件粒度，不监听整个 Pre-Proc/）
    // 避免 WZ 开发者修改测试文件时触发 Gateway 重编
    if let Ok(ns_entries) = fs::read_dir(preproc_dir) {
        for ns_entry in ns_entries.flatten() {
            let ns_path = ns_entry.path();
            if !ns_path.is_dir() {
                continue;
            }
            let ns_name = ns_path.file_name().and_then(|n| n.to_str()).unwrap_or("");
            if ns_name.is_empty() {
                continue;
            }
            let ns_lower = ns_name.to_lowercase();
            // 服务单元双路径扫描：历史位 Sources/Services + 重组后 Sources/Apps/Services
            //（65346a8d6 镜像重组迁移后者；按 service id 去重，Apps 位优先）
            let legacy_dir = ns_path.join("Sources").join("Services");
            let apps_dir = ns_path.join("Sources").join("Apps").join("Services");
            if !legacy_dir.exists() && !apps_dir.exists() {
                continue;
            }

            eprintln!(
                "build.rs: scanning services for namespace '{}' (legacy={} apps={})",
                ns_name,
                legacy_dir.exists(),
                apps_dir.exists()
            );

            if legacy_dir.exists() {
                scan_services(&legacy_dir, ns_name, &ns_lower, &mut service_entries);
            }
            if apps_dir.exists() {
                scan_services(&apps_dir, ns_name, &ns_lower, &mut service_entries);
            }
            // 去重：同 id 保留先扫到的（legacy 在先；Apps 位重复项丢弃并告警）
            let mut seen = std::collections::HashSet::new();
            service_entries.retain(|e| {
                if seen.insert((e.ns.clone(), e.id.clone())) {
                    true
                } else {
                    eprintln!(
                        "build.rs: duplicate service '{}' in namespace '{}' (Apps/Services 与 Services 同名)，已丢弃后扫项",
                        e.id, e.ns
                    );
                    false
                }
            });
        }
    }

    if service_entries.is_empty() {
        eprintln!("build.rs: no services found, generating empty registry");
    }

    // 按 (namespace, id) 排序保证输出稳定
    service_entries.sort_by(|a, b| a.ns.cmp(&b.ns).then(a.id.cmp(&b.id)));

    // === 生成 auto_service_registry.rs ===
    let out_dir = match std::env::var("OUT_DIR") {
        Ok(v) => v,
        Err(e) => {
            eprintln!("Error: OUT_DIR not set: {}", e);
            std::process::exit(1);
        }
    };

    let service_dest = Path::new(&out_dir).join("auto_service_registry.rs");
    let mut code = String::new();
    code.push_str("// Auto-generated by build.rs — DO NOT EDIT\n");
    code.push_str("//\n");
    code.push_str("// Generated by scanning ALL namespace service directories.\n");
    code.push_str("// Conditional compilation gates each service behind its cargo feature.\n");
    code.push('\n');
    code.push_str("use actix_web::web;\n");
    code.push('\n');

    // compiled_service_ids()
    code.push_str("/// IDs of all Service units compiled into this Gateway binary.\n");
    code.push_str("#[allow(dead_code)]\n");
    code.push_str("pub fn compiled_service_ids() -> &'static [&'static str] {\n");
    code.push_str("    &[\n");
    for entry in &service_entries {
        code.push_str(&format!(
            "        #[cfg(feature = \"{}-service-{}\")]\n",
            entry.ns_lower, entry.id
        ));
        code.push_str(&format!("        \"{}/{}\",\n", entry.ns, entry.id));
    }
    code.push_str("    ]\n");
    code.push_str("}\n");
    code.push('\n');

    // Imports
    for entry in &service_entries {
        code.push_str(&format!(
            "#[cfg(feature = \"{}-service-{}\")]\n",
            entry.ns_lower, entry.id
        ));
        code.push_str(&format!("use {};\n", entry.crate_name));
    }
    code.push('\n');

    // Per-namespace registration functions
    let mut ns_groups: std::collections::HashMap<String, Vec<&ServiceEntry>> =
        std::collections::HashMap::new();
    for entry in &service_entries {
        ns_groups.entry(entry.ns.clone()).or_default().push(entry);
    }
    for (ns, entries) in &ns_groups {
        let fn_name = format!("register_{}_routes", ns.to_lowercase().replace("-", "_"));
        code.push_str(&format!(
            "/// Auto-register Service routes for namespace '{}'.\n",
            ns
        ));
        code.push_str(&format!(
            "pub fn {}(cfg: &mut web::ServiceConfig) {{\n",
            fn_name
        ));
        for entry in entries {
            code.push_str(&format!(
                "    #[cfg(feature = \"{}-service-{}\")]\n",
                entry.ns_lower, entry.id
            ));
            code.push_str(&format!(
                "    {}::register_service_routes(cfg);\n",
                entry.crate_name
            ));
        }
        code.push_str("}\n\n");
    }

    // === Top-level dispatch: register_service_routes() ===
    code.push_str("/// Auto-generated top-level dispatch by namespace.\n");
    code.push_str(
        "/// Alias namespaces from NAMESPACE_ALIASES are expanded into their target's match arm.\n",
    );
    code.push_str("pub fn register_service_routes(cfg: &mut web::ServiceConfig) {\n");
    code.push_str("    let namespace = std::env::var(\"NAMESPACE\").unwrap_or_default();\n");
    code.push_str("    common::telemetry::info!(\"[service_registry] Registering routes for namespace '{}'\", namespace);\n");
    code.push('\n');
    code.push_str("    match namespace.as_str() {\n");

    // 为每个有 service 的 namespace 生成 match arm（自身 + 别名 target 的注册函数）
    for ns in ns_groups.keys() {
        let fn_name = format!("register_{}_routes", ns.to_lowercase().replace("-", "_"));

        code.push_str(&format!("        \"{}\" => {{\n", ns));
        // 自身 service 注册
        code.push_str(&format!("            {}(cfg);\n", fn_name));
        // 别名指向的 target namespace 的注册（如 Cosmic-Tools 别名 → Alioth：
        // Cosmic-Tools 部署同时需要 Alioth service 组 + 自有 ct-git service）
        for (alias, target) in NAMESPACE_ALIASES {
            if *alias == *ns {
                let target_fn = format!(
                    "register_{}_routes",
                    target.to_lowercase().replace("-", "_")
                );
                if ns_groups.contains_key(*target) {
                    code.push_str(&format!(
                        "            // alias '{}' → '{}'：同时注册 target service 组\n",
                        alias, target
                    ));
                    code.push_str(&format!("            {}(cfg);\n", target_fn));
                }
            }
        }
        code.push_str("        }\n");
    }

    code.push_str("        _ => {\n");
    code.push_str("            common::telemetry::warn!(\n");
    code.push_str("                \"[service_registry] Unknown namespace '{}', no service routes registered\",\n");
    code.push_str("                namespace\n");
    code.push_str("            );\n");
    code.push_str("        }\n");
    code.push_str("    }\n");
    code.push_str("}\n");
    code.push('\n');

    if let Err(e) = fs::write(&service_dest, &code) {
        eprintln!("Error: failed to write auto_service_registry.rs: {}", e);
        std::process::exit(1);
    }

    eprintln!(
        "Generated auto_service_registry.rs with {} services at {:?}",
        service_entries.len(),
        service_dest
    );
}

struct ServiceEntry {
    ns: String,
    ns_lower: String,
    id: String,
    crate_name: String,
}

fn scan_services(
    services_dir: &Path,
    ns_name: &str,
    ns_lower: &str,
    entries: &mut Vec<ServiceEntry>,
) {
    let dir_entries = match fs::read_dir(services_dir) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("build.rs: cannot read {:?}: {}", services_dir, e);
            return;
        }
    };

    let ns_crate = ns_lower.replace("-", "_");

    for dir_entry in dir_entries.flatten() {
        let path = dir_entry.path();
        if !path.is_dir() {
            continue;
        }

        let service_json = path.join("service.json");
        if !service_json.exists() {
            continue;
        }

        // 精确追踪每个 service.json 的变化
        println!("cargo:rerun-if-changed={}", service_json.display());

        let content = match fs::read_to_string(&service_json) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Warning: failed to read {:?}: {}", service_json, e);
                continue;
            }
        };

        let json: serde_json::Value = match serde_json::from_str(&content) {
            Ok(v) => v,
            Err(e) => {
                eprintln!("Warning: failed to parse {:?}: {}", service_json, e);
                continue;
            }
        };

        let service_id = json.get("id").and_then(|v| v.as_str()).unwrap_or("");
        if service_id.is_empty() {
            eprintln!(
                "Warning: service.json at {:?} has empty or missing 'id' field, skipping",
                service_json
            );
            continue;
        }

        // 验证 id 与目录名一致
        let dir_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
        if service_id != dir_name {
            eprintln!(
                "Warning: service '{}' at {:?} has id mismatch with directory name '{}', skipping",
                service_id, service_json, dir_name
            );
            continue;
        }

        let crate_name = format!("{}_service_{}", ns_crate, service_id.replace("-", "_"));
        let feature_name = format!("{}-service-{}", ns_lower, service_id);
        let cargo_feature = format!(
            "CARGO_FEATURE_{}",
            feature_name.to_uppercase().replace("-", "_")
        );

        if std::env::var(&cargo_feature).is_err() {
            eprintln!(
                "build.rs: skipping service '{}/{}' (feature '{}' not enabled)",
                ns_name, service_id, feature_name
            );
            continue;
        }

        eprintln!(
            "build.rs: found service '{}/{}' (crate: {})",
            ns_name, service_id, crate_name
        );

        entries.push(ServiceEntry {
            ns: ns_name.to_string(),
            ns_lower: ns_lower.to_string(),
            id: service_id.to_string(),
            crate_name,
        });
    }
}

/// 运行 ontology 一致性预检。
fn ontology_preflight_check() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let check_script = manifest_dir.join("../../scripts/check/check-ontology-sync.sh");

    if !check_script.exists() {
        eprintln!(
            "build.rs: 跳过 ontology 预检（脚本不存在: {:?}）",
            check_script
        );
        return;
    }

    let namespace = std::env::var("NAMESPACE").unwrap_or_else(|_| "Alioth".to_string());
    let strict = std::env::var("ONTOLOGY_CHECK_STRICT").is_ok();
    let db_url = std::env::var("DATABASE_URL").unwrap_or_default();

    // 仅当 DATABASE_URL 显式配置时才注入：空串会让 ontology-mapping 解析
    // 连接串失败（relative URL without a base），导致无 DB 配置的构建误报预检失败。
    let mut check_cmd = std::process::Command::new("bash");
    check_cmd.arg(&check_script).arg(&namespace);
    if !db_url.is_empty() {
        check_cmd.env("DATABASE_URL", &db_url);
    }
    let output = match check_cmd.output() {
        Ok(o) => o,
        Err(e) => {
            eprintln!("build.rs: 跳过 ontology 预检（无法执行脚本: {}）", e);
            return;
        }
    };

    let stderr = String::from_utf8_lossy(&output.stderr);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let has_errors = stderr.contains("❌") || stdout.contains("❌") || !output.status.success();

    if has_errors {
        let msg = format!(
            "⚠️  Ontology 预检不通过 (namespace={})\n\
             STDERR: {}\n\
             STDOUT: {}\n\
             请运行 `mise ontology-sync` 同步。\n\
             严格模式：ONTOLOGY_CHECK_STRICT=1 时阻塞构建。",
            namespace,
            stderr.trim(),
            stdout.trim()
        );
        if strict {
            panic!("❌ Ontology 预检失败（严格模式）:\n{}", msg);
        } else {
            eprintln!("{}", msg);
            println!("cargo:warning=Ontology 预检不通过 — 请运行 `mise ontology-sync` 修复");
        }
    } else {
        eprintln!("build.rs: ontology 预检通过 (namespace={})", namespace);
    }
}
